#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <limits.h>
#include <stdio.h>

long get_device_id_from_symlink(const char* link) {
    if (link == NULL || *link == '\0') {
        return -1;
    }

    struct stat statbuf;
    if (lstat(link, &statbuf) != 0) {
        return -1;
    }

    return (long) statbuf.st_dev;
}
